// Mini compute index — record JAH-GPCS-MINIPC-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"cpu_ghz": 4.4, "ram_gb": 16, "price_usd": 400};
var value = (m.cpu_ghz*m.ram_gb/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-MINIPC-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-MINIPC-000001|' + value.toFixed(2) + ' compute index');

